-- Ajout des nouvelles questions de quiz dans une base Cutshop déjà installée.
-- Fichier généré par scripts/generate-seed.ts : ne pas modifier à la main.
-- À coller dans le SQL Editor de Supabase. Sans risque si on le lance deux fois : une question déjà présente est ignorée.
begin;
commit;
select theme, count(*) as questions from public.quiz_questions group by theme order by theme;
